export default async function handler(req: VercelRequest, res: VercelResponse) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' })
  }

  // File names from the browser are ignored: the server looks them up (TRACKS).
  const { amount, email, name, trackIds: rawIds } = (req.body ?? {}) as {
    amount: number
    email: string
    name?: string
    trackIds: string[]
  }

  if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return res.status(400).json({ error: 'Valid email required' })
  }
  if (!Array.isArray(rawIds) || rawIds.length === 0 || rawIds.length > 50) {
    return res.status(400).json({ error: 'Invalid track selection' })
  }
  // Only tracks this store sells, each counted once.
  const trackIds = [...new Set(rawIds.map(String))]
  if (!trackIds.every(id => Object.prototype.hasOwnProperty.call(TRACKS, id))) {
    return res.status(400).json({ error: 'Invalid track selection' })
  }
  const cleanName = typeof name === 'string' ? name.trim().slice(0, 100) : ''

  const minRequiredAmount = trackIds.length * 3;
  if (!amount || typeof amount !== 'number' || amount < minRequiredAmount || amount > 500) {
    return res.status(400).json({ error: 'Invalid amount' })
  }

  try {
    const siteUrl = process.env.SITE_URL || 'https://djdxmusic.com';

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      customer_email: email,
      line_items: [
        {
          price_data: {
            currency: 'usd',
            product_data: {
              // Name the music: shown on the payment page, receipt and bank statement.
              name: trackIds.length === 1
                ? `“${TRACKS[trackIds[0]].title}” by DJ DX`
                : `DJ DX: ${trackIds.length} tracks`,
              ...(trackIds.length > 1 ? { description: trackIds.map(id => TRACKS[id].title).join(' · ').slice(0, 480) } : {}),
            },
            unit_amount: Math.round(amount * 100), // convert to cents
          },
          quantity: 1,
        },
      ],
      mode: 'payment',
      // No personal details in the address: it ends up in history and logs.
      success_url: `${siteUrl}/thank-you`,
      cancel_url: `${siteUrl}/music`,
      metadata: {
        trackIds: trackIds.join(','),
        customerEmail: email,
        customerName: cleanName,
      },
    });

    return res.status(200).json({
      sessionId: session.id,
      checkoutUrl: session.url,
    })
  } catch (error) {
    console.error('Checkout error:', error)
    return res.status(500).json({ error: 'Internal server error' })
  }
}
